package com.gamesapp.multiplayer.games.classic\n\nimport com.gamesapp.multiplayer.games.GameEngine\nimport com.gamesapp.multiplayer.models.GameMove\nimport com.gamesapp.multiplayer.models.Player\n\nclass ConnectFour : GameEngine() {\n    override val gameId = 4\n    override val gameName = \"Connect Four\"\n    \n    private val board = Array(6) { IntArray(7) }\n    private var moveCount = 0\n\n    override fun makeMove(move: GameMove): Boolean {\n        val col = move.moveData.toIntOrNull() ?: return false\n        if (col < 0 || col >= 7 || board[0][col] != 0) return false\n\n        val playerNum = if (move.playerId == player1?.id) 1 else 2\n        \n        for (row in 5 downTo 0) {\n            if (board[row][col] == 0) {\n                board[row][col] = playerNum\n                moveCount++\n                break\n            }\n        }\n\n        checkWinner()?.let { winner = it; gameOver = true }\n        if (moveCount == 42) gameOver = true\n\n        switchPlayer()\n        return true\n    }\n\n    override fun isValidMove(move: GameMove): Boolean {\n        val col = move.moveData.toIntOrNull() ?: return false\n        return col in 0..6 && board[0][col] == 0\n    }\n\n    override fun switchPlayer() {\n        currentPlayer = if (currentPlayer?.id == player1?.id) player2 else player1\n    }\n\n    override fun checkWinner(): Player? {\n        for (i in 0..5) {\n            for (j in 0..6) {\n                if (board[i][j] == 0) continue\n                val player = if (board[i][j] == 1) player1 else player2\n                if (checkDirection(i, j, 0, 1) || checkDirection(i, j, 1, 0) ||\n                    checkDirection(i, j, 1, 1) || checkDirection(i, j, 1, -1)) {\n                    return player\n                }\n            }\n        }\n        return null\n    }\n\n    private fun checkDirection(row: Int, col: Int, dRow: Int, dCol: Int): Boolean {\n        val piece = board[row][col]\n        var count = 1\n        var r = row + dRow\n        var c = col + dCol\n        while (r in 0..5 && c in 0..6 && board[r][c] == piece) {\n            count++\n            r += dRow\n            c += dCol\n        }\n        return count >= 4\n    }\n\n    override fun getGameState(): String = board.joinToString(\";\") { it.joinToString(\",\") }\n}\n", "path": "app/src/main/java/com/gamesapp/multiplayer/games/classic/ConnectFour.kt"}, {"content": "package com.gamesapp.multiplayer.games.action\n\nimport com.gamesapp.multiplayer.games.GameEngine\nimport com.gamesapp.multiplayer.models.GameMove\nimport com.gamesapp.multiplayer.models.Player\n\nclass SnakeBattle : GameEngine() {\n    override val gameId = 45\n    override val gameName = \"Snake Battle\"\n\n    private data class Point(var x: Int, var y: Int)\n    \n    private val snake1 = mutableListOf(Point(10, 10))\n    private val snake2 = mutableListOf(Point(20, 20))\n    private var direction1 = Pair(1, 0)\n    private var direction2 = Pair(-1, 0)\n    private var food = Point(15, 15)\n    private var player1Score = 0\n    private var player2Score = 0\n    private val gridSize = 30\n\n    override fun makeMove(move: GameMove): Boolean {\n        val direction = move.moveData.split(\",\")\n        if (direction.size != 2) return false\n        val dx = direction[0].toIntOrNull() ?: return false\n        val dy = direction[1].toIntOrNull() ?: return false\n\n        if (move.playerId == player1?.id) {\n            direction1 = Pair(dx, dy)\n        } else {\n            direction2 = Pair(dx, dy)\n        }\n\n        updateGame()\n        return true\n    }\n\n    private fun updateGame() {\n        moveSnake(snake1, direction1)\n        moveSnake(snake2, direction2)\n\n        if (snake1.first() == food) {\n            player1Score += 10\n            snake1.add(Point(0, 0))\n            food = Point((Math.random() * gridSize).toInt(), (Math.random() * gridSize).toInt())\n        }\n        if (snake2.first() == food) {\n            player2Score += 10\n            snake2.add(Point(0, 0))\n            food = Point((Math.random() * gridSize).toInt(), (Math.random() * gridSize).toInt())\n        }\n\n        if (checkCollision()) {\n            gameOver = true\n            winner = if (player1Score > player2Score) player1 else player2\n        }\n    }\n\n    private fun moveSnake(snake: MutableList<Point>, direction: Pair<Int, Int>) {\n        val head = snake.first()\n        val newHead = Point((head.x + direction.first) % gridSize, (head.y + direction.second) % gridSize)\n        snake.add(0, newHead)\n        snake.removeAt(snake.size - 1)\n    }\n\n    private fun checkCollision(): Boolean {\n        return snake1.drop(1).contains(snake1.first()) || snake2.drop(1).contains(snake2.first())\n    }\n\n    override fun isValidMove(move: GameMove): Boolean = true\n    override fun switchPlayer() {}\n    override fun checkWinner(): Player? = winner\n    override fun getGameState(): String = \"$player1Score,$player2Score\"\n}\n", "path": "app/src/main/java/com/gamesapp/multiplayer/games/action/SnakeBattle.kt"}, {"content": "package com.gamesapp.multiplayer.games.action\n\nimport com.gamesapp.multiplayer.games.GameEngine\nimport com.gamesapp.multiplayer.models.GameMove\nimport com.gamesapp.multiplayer.models.Player\n\nclass TankBattle : GameEngine() {\n    override val gameId = 38\n    override val gameName = \"Tank Battle\"\n\n    private data class Tank(var x: Float, var y: Float, var angle: Float, var health: Int = 100)\n    private data class Projectile(var x: Float, var y: Float, var velX: Float, var velY: Float)\n\n    private val tank1 = Tank(100f, 300f, 0f)\n    private val tank2 = Tank(700f, 300f, 180f)\n    private val projectiles = mutableListOf<Projectile>()\n    private var player1Score = 0\n    private var player2Score = 0\n\n    override fun makeMove(move: GameMove): Boolean {\n        val action = move.moveData\n        val tank = if (move.playerId == player1?.id) tank1 else tank2\n\n        when (action) {\n            \"LEFT\" -> tank.angle -= 5\n            \"RIGHT\" -> tank.angle += 5\n            \"UP\" -> {\n                tank.y -= 5\n                if (tank.y < 0) tank.y = 0f\n            }\n            \"DOWN\" -> {\n                tank.y += 5\n                if (tank.y > 600) tank.y = 600f\n            }\n            \"SHOOT\" -> {\n                val radians = Math.toRadians(tank.angle.toDouble())\n                projectiles.add(Projectile(\n                    tank.x,\n                    tank.y,\n                    (Math.cos(radians) * 10).toFloat(),\n                    (Math.sin(radians) * 10).toFloat()\n                ))\n            }\n        }\n\n        updateProjectiles()\n        return true\n    }\n\n    private fun updateProjectiles() {\n        projectiles.forEach { proj ->\n            proj.x += proj.velX\n            proj.y += proj.velY\n        }\n\n        projectiles.removeAll { proj ->\n            val hitTank1 = Math.abs(proj.x - tank1.x) < 20 && Math.abs(proj.y - tank1.y) < 20\n            val hitTank2 = Math.abs(proj.x - tank2.x) < 20 && Math.abs(proj.y - tank2.y) < 20\n\n            when {\n                hitTank1 -> { tank1.health -= 10; player2Score += 10; true }\n                hitTank2 -> { tank2.health -= 10; player1Score += 10; true }\n                else -> proj.x < 0 || proj.x > 800 || proj.y < 0 || proj.y > 600\n            }\n        }\n\n        if (tank1.health <= 0 || tank2.health <= 0) {\n            gameOver = true\n            winner = if (player1Score > player2Score) player1 else player2\n        }\n    }\n\n    override fun isValidMove(move: GameMove): Boolean = true\n    override fun switchPlayer() {}\n    override fun checkWinner(): Player? = winner\n    override fun getGameState(): String = \"${tank1.x},${tank1.y},${tank2.x},${tank2.y},$player1Score,$player2Score\"\n}\n", "path": "app/src/main/java/com/gamesapp/multiplayer/games/action/TankBattle.kt"}, {"content": "package com.gamesapp.multiplayer.games.action\n\nimport com.gamesapp.multiplayer.games.GameEngine\nimport com.gamesapp.multiplayer.models.GameMove\nimport com.gamesapp.multiplayer.models.Player\n\nclass BrickBreaker : GameEngine() {\n    override val gameId = 37\n    override val gameName = \"Brick Breaker\"\n\n    private var ballX = 400f\n    private var ballY = 500f\n    private var ballVelX = 5f\n    private var ballVelY = -5f\n    private var paddle1X = 150f\n    private var paddle2X = 600f\n    private var player1Score = 0\n    private var player2Score = 0\n    private val bricks = Array(5) { IntArray(8) { 1 } }\n\n    override fun makeMove(move: GameMove): Boolean {\n        val direction = move.moveData\n        if (move.playerId == player1?.id) {\n            when (direction) {\n                \"LEFT\" -> paddle1X = maxOf(0f, paddle1X - 15)\n                \"RIGHT\" -> paddle1X = minOf(750f, paddle1X + 15)\n            }\n        } else {\n            when (direction) {\n                \"LEFT\" -> paddle2X = maxOf(0f, paddle2X - 15)\n                \"RIGHT\" -> paddle2X = minOf(750f, paddle2X + 15)\n            }\n        }\n        updateBall()\n        return true\n    }\n\n    private fun updateBall() {\n        ballX += ballVelX\n        ballY += ballVelY\n\n        if (ballX <= 0 || ballX >= 800) ballVelX = -ballVelX\n        if (ballY <= 0) ballVelY = -ballVelY\n\n        if (ballY in 480f..520f && ((ballX in paddle1X..(paddle1X + 100)) || (ballX in paddle2X..(paddle2X + 100)))) {\n            ballVelY = -ballVelY\n        }\n\n        for (i in 0..4) {\n            for (j in 0..7) {\n                if (bricks[i][j] == 1) {\n                    val brickX = j * 100\n                    val brickY = i * 30\n                    if (ballX in brickX.toFloat()..(brickX + 100).toFloat() && ballY in brickY.toFloat()..(brickY + 30).toFloat()) {\n                        bricks[i][j] = 0\n                        ballVelY = -ballVelY\n                        if (ballY < paddle1Y) player1Score += 10 else player2Score += 10\n                    }\n                }\n            }\n        }\n\n        if (ballY > 600) {\n            gameOver = true\n            winner = if (player1Score > player2Score) player1 else player2\n        }\n    }\n\n    override fun isValidMove(move: GameMove): Boolean = true\n    override fun switchPlayer() {}\n    override fun checkWinner(): Player? = winner\n    override fun getGameState(): String = \"$ballX,$ballY,$player1Score,$player2Score\"\n    private val paddle1Y = 500f\n}\n", "path": "app/src/main/java/com/gamesapp/multiplayer/games/action/BrickBreaker.kt"}, {"content": "package com.gamesapp.multiplayer.games.puzzle\n\nimport com.gamesapp.multiplayer.games.GameEngine\nimport com.gamesapp.multiplayer.models.GameMove\nimport com.gamesapp.multiplayer.models.Player\n\nclass Minesweeper : GameEngine() {\n    override val gameId = 22\n    override val gameName = \"Minesweeper\"\n\n    private val grid = Array(8) { IntArray(8) }\n    private val revealed = Array(8) { BooleanArray(8) }\n    private var player1Score = 0\n    private var player2Score = 0\n    private val mineCount = 10\n\n    init {\n        generateMines()\n    }\n\n    private fun generateMines() {\n        var minesPlaced = 0\n        while (minesPlaced < mineCount) {\n            val row = (Math.random() * 8).toInt()\n            val col = (Math.random() * 8).toInt()\n            if (grid[row][col] != -1) {\n                grid[row][col] = -1\n                minesPlaced++\n            }\n        }\n        for (i in 0..7) {\n            for (j in 0..7) {\n                if (grid[i][j] != -1) {\n                    grid[i][j] = countAdjacentMines(i, j)\n                }\n            }\n        }\n    }\n\n    private fun countAdjacentMines(row: Int, col: Int): Int {\n        var count = 0\n        for (i in -1..1) {\n            for (j in -1..1) {\n                val r = row + i\n                val c = col + j\n                if (r in 0..7 && c in 0..7 && grid[r][c] == -1) count++\n            }\n        }\n        return count\n    }\n\n    override fun makeMove(move: GameMove): Boolean {\n        val data = move.moveData.split(\",\")\n        if (data.size != 2) return false\n\n        val row = data[0].toIntOrNull() ?: return false\n        val col = data[1].toIntOrNull() ?: return false\n\n        if (revealed[row][col]) return false\n        revealed[row][col] = true\n\n        if (grid[row][col] == -1) {\n            gameOver = true\n            winner = if (move.playerId == player1?.id) player2 else player1\n            return true\n        }\n\n        if (move.playerId == player1?.id) player1Score++ else player2Score++\n\n        var allRevealed = true\n        for (i in 0..7) {\n            for (j in 0..7) {\n                if (!revealed[i][j]) allRevealed = false\n            }\n        }\n        if (allRevealed) {\n            gameOver = true\n            winner = if (player1Score > player2Score) player1 else player2\n        }\n\n        return true\n    }\n\n    override fun isValidMove(move: GameMove): Boolean {\n        val data = move.moveData.split(\",\")\n        val row = data[0].toIntOrNull() ?: return false\n        val col = data[1].toIntOrNull() ?: return false\n        return row in 0..7 && col in 0..7 && !revealed[row][col]\n    }\n\n    override fun switchPlayer() {\n        currentPlayer = if (currentPlayer?.id == player1?.id) player2 else player1\n    }\n\n    override fun checkWinner(): Player? = winner\n    override fun getGameState(): String = \"$player1Score,$player2Score\"\n}\n", "path": "app/src/main/java/com/gamesapp/multiplayer/games/puzzle/Minesweeper.kt"}]